import sys
from functools import reduce

MOD = 998244353

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    X = int(data[1], 2)
    A = [int(data[i + 2], 2) for i in range(N)]

    reachable = set(A)

    def can_reach(x):
        if x in reachable:
            return True
        for a in A:
            if x ^ a in reachable:
                return True
            if x < a * 2:
                break
            if (x // 2) ^ a in reachable:
                return True
        return False

    result = sum(can_reach(i) for i in range(X + 1)) % MOD
    print(result)

if __name__ == "__main__":
    main()
